request.description:
The endpoint retrieves the details of a specific kiosk within an organization. The response is a JSON object containing various attributes such as ewt_on_waiting_enabled, label, logo, queues, kiosk_mode, checkin_mode, site_timezone, address, support_fields, checkin_basic_data, checkin_fields, and serving.

``` json
{
  "type": "object",
  "properties": {
    "ewt_on_waiting_enabled": { "type": "boolean" },
    "_id": { "type": "string" },
    "label": { "type": "string" },
    "organization_label": { "type": "string" },
    "logo": { "type": "string" },
    "bkg_color_01": { "type": "string" },
    "bkg_color_02": { "type": "string" },
    "queues": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "_id": { "type": "string" },
          "label": { "type": "string" },
          "color": { "type": "string" },
          "type": { "type": "integer" },
          "queues": { "type": "array" }
        }
      }
    },
    "kiosk_mode": { "type": "boolean" },
    "checkin_mode": { "type": "integer" },
    "site_timezone": { "type": "string" },
    "mobile_qrcode": { "type": "string" },
    "info_01": { "type": "string" },
    "info_03": { "type": "string" },
    "multiple_waiting_enable": { "type": "boolean" },
    "ticket_qrcode": { "type": "boolean" },
    "address": {
      "type": "object",
      "properties": {
        "address_01": { "type": "string" },
        "number": { "type": "string" },
        "address_02": { "type": "string" },
        "address_03": { "type": "string" },
        "zipcode": { "type": "string" },
        "city": { "type": "string" },
        "state": { "type": "string" },
        "geolocation": {
          "type": "object",
          "properties": {
            "type": { "type": "string" },
            "coordinates": { "type": "array" }
          }
        }
      }
    },
    "late_checkin": { "type": "boolean" },
    "support_fields": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "options": { "type": "array" },
          "input": { "type": "string" },
          "label": { "type": "string" },
          "type": { "type": "string" },
          "required": { "type": "boolean" },
          "sensible": { "type": "boolean" },
          "internal": { "type": "boolean" }
        }
      }
    },
    "checkin_basic_data": {
      "type": "object",
      "properties": {
        "name": {
          "type": "object",
          "properties": {
            "enable": { "type": "boolean" },
            "label": { "type": "string" },
            "required": { "type": "boolean" }
          }
        },
        "mobile": {
          "type": "object",
          "properties": {
            "enable": { "type": "boolean" },
            "label": { "type": "string" },
            "required": { "type": "boolean" }
          }
        },
        "ewt": {
          "type": "object",
          "properties": {
            "enable": { "type": "boolean" },
            "label": { "type": "string" },
            "required": { "type": "boolean" }
          }
        }
      }
    },
    "serving": { "type": "boolean" }
  }
}

 ```

